sys_script_include.script:
var CLMApproverMappingCheck = Class.create();
CLMApproverMappingCheck.prototype = {
  initialize: function() {},

  LABEL: { TSH_BPD:'TSH BPD', ZH_BPD:'ZH BPD', RH_CH_RMC:'RH/CH', ZH_RMC:'ZH', HEAD_RMC:'Head RMC',
           HEAD_KEY_RMC:'Head Key & RMC', CH_RMC:'CH RMC', HSBPD:'HS BPD', HBPD:'HBPD' },

  // roles: role keys in the chain (incl. ZCH / HO when CV applies)
  // returns array of display labels with no active mapped user
  findMissing: function(customerSysId, roles, isCementBpd) {
    var missing = [];
    var custGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
    if (!custGr.get(customerSysId)) return ['Customer record not found'];

    var region  = custGr.region  + '';
    var zone    = custGr.zone    + '';
    var depot   = custGr.depot   + '';
    var segment = custGr.segment + '';
    var cb      = (isCementBpd === true || isCementBpd === 'true') && segment === 'BPD';

    var resolver = new CLMUserResolver();
    var seen = {};

    for (var i = 0; i < roles.length; i++) {
      var role = roles[i];
      var key  = resolver._normalizeRole(role);
      if (seen[key]) continue;          // CMO/BH, NSH_CCH/CCH etc. checked once
      seen[key] = true;

      var userId = '';
      try { userId = resolver.getUser(role, region, zone, segment, depot, cb) + ''; }
      catch (e) { userId = ''; }

      var ok = false;
      if (userId && userId !== 'null') {
        var u = new GlideRecord('sys_user');
        ok = u.get(userId) && (u.active + '') === 'true';
      }
      if (!ok) missing.push(this.LABEL[role] || this.LABEL[key] || key);
    }
    return missing;
  },
  type: 'CLMApproverMappingCheck'
};
